	// Phase 0: initialize temporaries
	// ---------------------------------------------------------------------

	// tmp[i][j] = 0
	traverser(tmp).for_each([=](auto state) {
		tmp[state] = (num_t)0;
	});

	// D[i][l] *= beta
	traverser(D).for_each([=](auto state) {
		D[state] *= beta;
	});

