	// Phase 1: tmp[i][j] += alpha * sum_k A[i][k] * B[k][j]
	//
	// Loop order: i (outer) -> k -> j (inner)
	//
	// Layout considerations:
	//   A:   dims 'i','k'  (k contiguous)
	//   B:   dims 'k','j'  (j contiguous)
	//   tmp: dims 'i','j'  (j contiguous)
	//
