		// i is fixed here
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			// i and k are fixed here

			// Hoist A[i,k] * alpha out of the innermost j-loop
			const num_t a_ik_alpha = alpha * A[trav_ik];

			// Iterate over j as the innermost dimension (contiguous in B and tmp)
			trav_ik.template for_dims<'j'>([=](auto trav_ikj) {
				// trav_ikj has i,k,j fixed
				tmp[trav_ikj] += a_ik_alpha * B[trav_ikj];
			});
		});
	});

	// ---------------------------------------------------------------------
	// Phase 2: D[i][l] += sum_j tmp[i][j] * C[j][l]
	//
	// (Recall D has already been scaled by beta above.)
	//
	// Loop order: i (outer) -> j -> l (inner)
	//
	// Layout considerations:
	//   tmp: dims 'i','j'  (j contiguous)
	//   C:   dims 'j','l'  (l contiguous)
	//   D:   dims 'i','l'  (l contiguous)
	//
	// For a fixed (i,j):
	//   - tmp[i,j] is a single scalar, reused across the whole inner l loop
	//   - C[j,l] is read as a contiguous row in 'l'
	//   - D[i,l] is updated as a contiguous row in 'l'
	// ---------------------------------------------------------------------
	traverser(tmp, C, D).template for_dims<'i'>([=](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// i and j are fixed here

			// Hoist tmp[i,j] out of the innermost l-loop
			const num_t tmp_ij = tmp[trav_ij];

			// Iterate over l as the innermost dimension (contiguous in C and D)
			trav_ij.template for_dims<'l'>([=](auto trav_ijl) {
				// trav_ijl has i,j,l fixed
				D[trav_ijl] += tmp_ij * C[trav_ijl];
			});
		});
	});

#pragma endscop
