	//    special-case the first k. This preserves the original semantics
	//    (one zeroing and then a sum over k) while allowing a better loop
	//    ordering for locality in the next step.
	traverser(tmp).for_each([&](auto state) {
		tmp[state] = (num_t)0;
	});

	// 2) Accumulate over k with loop order: i -> k -> j
	//
	//    For fixed (i, k):
	//      - A[i,k] is loaded once and reused for all j.
	//      - B[k,j] and tmp[i,j] are accessed with j as the innermost
	//        dimension, which is their contiguous dimension in memory.
	traverser(tmp, A, B).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// i and k are fixed here
			const num_t a_ik = A[trav_ik];
			const num_t scaled_a_ik = alpha * a_ik;

			// j is innermost: contiguous access in tmp (i,j) and B (k,j)
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				tmp[trav_ikj] += scaled_a_ik * B[trav_ikj];
			});
		});
	});

