	// Phase 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// ---------------------------------------------------------------------

	// 1) Scale D by beta in a standalone pass.
	//    This keeps the main accumulation loop free from extra dependences
	//    and matches the original formula exactly.
	traverser(D).for_each([&](auto state) {
		D[state] *= beta;
	});

	// 2) Accumulate over j with loop order: i -> j -> l
	//
	//    For fixed (i, j):
	//      - tmp[i,j] is loaded once and reused for all l.
	//      - C[j,l] and D[i,l] are accessed with l as the innermost
	//        dimension, their contiguous dimension in memory.
	traverser(D, tmp, C).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// i and j are fixed here
			const num_t tmp_ij = tmp[trav_ij];

			// l is innermost: contiguous access in C (j,l) and D (i,l)
			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				D[trav_ijl] += tmp_ij * C[trav_ijl];
			});
		});
	});
#pragma endscop
}

} // namespace

